const RSP = R5.rs.policies, rsRow = p => { const o = RSP[`0.1|${p}`]; return [PN7[p], pct2(o.med), `${pct2(o.q25)}–${pct2(o.q75)}`, `${pct2(o.min)}–${o.max >= 1000 ? Math.round(o.max) : pct2(o.max)}`, `${o.fail_splits}`]; };
S.push(P0(`**Thirty random 80/20 splits of FD001.** Each split (permutation seed 31000 + *s*, inner seed 3100 + *s*) re-selects every setting on its 80 training engines and evaluates the 20 test engines once. The splits share engines, so their results are summarised by their distribution, without a pooled interval.`));
S.push(...tableS('FD001, thirty random 80/20 splits, *c*_{p}/*c*_{c} = 0.1: distribution of *M* (%) over the splits and the number of splits with at least one test failure.', ['Policy', 'Median', 'Interquartile range', 'Range', 'Splits with a failure'],
  ['P1_cls_q', 'P1_cls_opt_mid', 'P1_res_q', 'P1_res_opt_mid', 'P3_res60', 'P3_res125', 'STW_cost', 'STW_cost_1se', 'STW_window', 'HI_cost', 'age_grid'].filter(p => RSP[`0.1|${p}`]).map(rsRow), [2600, 1300, 1800, 1800, 1526]));
const RSQ = R5.rs.pairs, rqRow = (a, b) => { const o = RSQ[`0.1|${a}|${b}`]; return [`${PN7[a]} − ${PN7[b]}`, sgn2(o.med), `${f1(100 * o.share_a)}%`, `${o.below} / ${o.above}`]; };
S.push(...tableS('FD001, thirty random splits, *c*_{p}/*c*_{c} = 0.1: paired differences in *M* (percentage points; ours minus theirs).', ['Comparison', 'Median difference', 'Splits in which ours is lower', 'Splits whose own interval lies below / above 0'],
  [['STW_window', 'P1_res_opt_mid'], ['STW_cost_1se', 'P1_res_opt_mid'], ['STW_window', 'P1_cls_opt_mid'], ['STW_cost_1se', 'P1_cls_opt_mid'], ['STW_window', 'P3_res60']].map(([a, b]) => rqRow(a, b)), [3600, 1600, 1900, 1926]));
const BNS = KM.fd001.bins, THS = KM.fd001.thresholds;
S.push(P0(`**Probability models.** For P-res, equal-count bins of the inner out-of-fold estimates of the cap-60 regressor were merged until each held at least 200 rows; this left ${KM.fd001.bins_count['60'][0]}–${KM.fd001.bins_count['60'][2]} bins with cap 60 (equal-count edges collapse near the cap) and ${KM.fd001.bins_count['125'][0]}–${KM.fd001.bins_count['125'][2]} with cap 125 on FD001. The three lowest bins, which decide Pr(RUL ≤ 10), each held at least ${BNS.rows_min} rows from ${BNS.units_min} or more distinct training engines, with upper edges near ${BNS.hi.map(x => Math.round(x)).join(', ')} cycles, so P-res policy 1 acts, in effect, when the estimate falls below about ${f1(BNS.hi[1])} cycles. Monotonicity was enforced by isotonic regression and changed no bin value. The optimised thresholds (median over folds, middle of the tie) were ${['cls', 'res'].map(m => `${m === 'cls' ? 'P-cls' : 'P-res'} ${THS[`0.1|${m}`].mid.toPrecision(2)}`).join(' and ')} at *c*_{p}/*c*_{c} = 0.1, below the heuristic value of 0.1, as in their simulations.`));
const TLp = ['P1_cls_opt_mid', 'P1_cls_opt_max', 'P1_cls_q', 'P1_res_opt_mid', 'P1_res_opt_max', 'P1_res_q', 'STW_cost', 'STW_cost_1se', 'STW_window', 'HI_cost', 'P3_res60'];
S.push(...tableS('Robustness of threshold optimisation: number of test sets × cost ratios with at least one test failure (in brackets: with *M* > 50%), at *c*_{p}/*c*_{c} ≤ 0.1 and over all seven ratios.', ['Policy', ...KDS.map(d => `${d.toUpperCase()} (≤ 0.1, of 20)`), 'FD001, 30 splits (≤ 0.1, of 120)', 'All datasets, all ratios (five-fold, of 140)'],
  TLp.map(p => [PN7[p], ...KDS.map(d => `${TL(d, 'cv', p).fail_small} (${TL(d, 'cv', p).M50_small})`), `${TL('fd001', 'rs', p).fail_small} (${TL('fd001', 'rs', p).M50_small})`, `${KDS.reduce((a, d) => a + TL(d, 'cv', p).fail, 0)}`]),
  [2300, 1250, 1250, 1250, 1250, 1500, 1226], `Decision rule fixed before the run: the claim that direct cost tuning is fragile is supported on a dataset if each plainly optimised policy (P1 P-cls opt, P1 P-res opt, STW cost) fails in more cells at ratios ≤ 0.1 than its counterpart (P1 with *p* = *c*_{p}/*c*_{c}; STW cost 1-SE). Verdicts: ${KDS.map(d => `${d.toUpperCase()} ${FRG.verdict[`${d}|cv`]}`).join(', ')}; thirty FD001 splits ${FRG.verdict['fd001|rs']}.`));

