S.push(H1('S18. Calibrated health-indicator alarm at every warning level'));
const HCD = ['PHM08', 'FD001', 'FD002', 'FD003', 'FD004', 'NCMAPSS6'];
S.push(...tableS('In-window rate (%) of the recipe, the health-indicator threshold alarm and the calibrated indicator with the recipe\'s trigger, at every warning level (five-fold cross-validation; exact McNemar *p*, unadjusted, calibrated indicator against the recipe).', ['Dataset', '*H*', 'Recipe', 'Health-indicator alarm', 'Calibrated indicator', 'Late / early / missed (calibrated)', 'Recipe only / calibrated only; *p*'],
  HCD.flatMap(d => ['10', '15', '20', '30', '40'].map((H, i) => { const o = HC[d][H]; return [i === 0 ? RNAME[d] : '', H, f1(100 * o.recipe_IN / o.n), f1(100 * o.hi_IN / o.n), f1(o.pct), `${o.late} / ${o.early} / ${o.missed}`, `${o.vs_recipe.only_a} / ${o.vs_recipe.only_b}; ${fmtp(o.vs_recipe.p)}`]; })),
  [1500, 500, 1000, 1500, 1300, 1700, 1726], 'The isotonic map from indicator value to min(*r*, *c*) and the trigger settings are chosen on the inner out-of-fold values of the training units; the indicator itself is the one of the health-indicator alarm, which this analysis reproduces unit by unit before calibration.'));
